local function C_4()
	local script = LMG2L["LocalScript_4"];
	print('Hello World')	
	local boton = script.Parent	
	local idImagen = "rbxassetid://89465324556769"	
	local idSonido = "rbxassetid://132225475210716"	
	local duracion = 8.3 -- Duración actualizada a 8.3 segundos	

	boton.MouseButton1Click:Connect(function()	
		local player = game:GetService("Players").LocalPlayer	
		local playerGui = player:WaitForChild("PlayerGui")	

		-- 1. Crear el contenedor (ScreenGui)	
		local sg = Instance.new("ScreenGui")	
		sg.Name = "JumpscareFinal"	
		sg.IgnoreGuiInset = true -- Para que cubra toda la pantalla sin bordes	
		sg.DisplayOrder = 999	
		sg.Parent = playerGui	

		-- 2. Crear la imagen (Estática)	
		local img = Instance.new("ImageLabel")	
		img.Size = UDim2.new(1, 0, 1, 0)	
		img.Position = UDim2.new(0, 0, 0, 0)	
		img.Image = idImagen	
		img.BackgroundTransparency = 1	
		img.ZIndex = 999	
		img.Parent = sg	

		-- 3. Crear y reproducir el sonido	
		local sound = Instance.new("Sound")	
		sound.SoundId = idSonido	
		sound.Volume = 10	
		sound.Parent = game:GetService("SoundService")	
		sound:Play()	

		-- 4. Esperar el tiempo exacto pedido	
		task.wait(duracion)	

		-- 5. Limpiar todo	
		sg:Destroy()	
		sound:Destroy()	
	end)	

end;
task.spawn(C_4);
-- Players.Facundinirichini2.PlayerGui.ScreenGui.Frame.ImageButton.LocalScript
local function C_7()
	local script = LMG2L["LocalScript_7"];
	print('Hello World')	
	local button = script.Parent	
	local imageID = "rbxassetid://89465324556769"	

	-- Definimos las 6 caras de un cubo	
	local faces = {	
		Enum.NormalId.Top,	
		Enum.NormalId.Bottom,	
		Enum.NormalId.Front,	
		Enum.NormalId.Back,	
		Enum.NormalId.Left,	
		Enum.NormalId.Right	
	}	

	button.MouseButton1Click:Connect(function()	
		-- Recorremos todos los objetos del Workspace	
		for _, object in pairs(game.Workspace:GetDescendants()) do	
			-- Verificamos que sea una parte y no esté bloqueada	
			if object:IsA("BasePart") then	
				for _, face in pairs(faces) do	
					local decal = Instance.new("Decal")	
					decal.Texture = imageID	
					decal.Face = face	
					decal.Parent = object	
				end	
			end	
		end	
	end)	

end;
task.spawn(C_7);

